impl curl_hstsentry {
    pub fn includeSubDomains(&self) -> bool {
        self._bits_16[0] & (1 << 0) != 0
    }
    pub fn set_includeSubDomains(&mut self, on: bool) {
        if on {
            self._bits_16[0] |= 1 << 0;
        } else {
            self._bits_16[0] &= !(1 << 0);
        }
    }
}
